def qr(size,fg=AUB,bg='#fff',seed=3):
    random.seed(seed);n=21;c=size/n;o=f'<svg viewBox="0 0 {size} {size}" style="width:{size}px;height:{size}px"><rect width="{size}" height="{size}" fill="{bg}"/>'
    def finder(x,y):return f'<rect x="{x*c}" y="{y*c}" width="{7*c}" height="{7*c}" fill="{fg}"/><rect x="{(x+1)*c}" y="{(y+1)*c}" width="{5*c}" height="{5*c}" fill="{bg}"/><rect x="{(x+2)*c}" y="{(y+2)*c}" width="{3*c}" height="{3*c}" fill="{fg}"/>'
    for i in range(n):
        for j in range(n):
            if (i<8 and j<8) or (i>n-9 and j<8) or (i<8 and j>n-9):continue
            if random.random()<.48:o+=f'<rect x="{i*c}" y="{j*c}" width="{c}" height="{c}" fill="{fg}"/>'
    return o+finder(0,0)+finder(n-7,0)+finder(0,n-7)+'</svg>'
