phone=f'''<div style="width:240px;height:480px;background:#111;border-radius:34px;padding:10px;{SH}"><div style="width:100%;height:100%;border-radius:26px;background:{IVORY};overflow:hidden;position:relative;padding:18px 14px"><div style="display:flex;justify-content:space-between;align-items:center"><div style="width:70px">{lk(AUB,"wm")}</div><div style="width:24px;height:24px;color:{AUB}">{A2.icon_inline("bag")}</div></div><div style="margin-top:14px;display:flex;gap:6px;font-size:10px;font-weight:700"><span style="background:{AUB};color:{IVORY};padding:5px 12px;border-radius:20px">Bowls</span><span style="background:#fff;padding:5px 12px;border-radius:20px">Greens</span><span style="background:#fff;padding:5px 12px;border-radius:20px">Wraps</span></div>{''.join(f'<div style="display:flex;gap:10px;margin-top:12px;background:#fff;border-radius:14px;padding:8px;align-items:center"><div style="width:54px;height:54px;border-radius:27px 27px 8px 8px;overflow:hidden;flex:none">{bowl(s,54,c)}</div><div><div style="font-weight:800;font-size:11px">{n}</div><div style="font-size:10px;opacity:.6">{k}</div><div style="font-weight:800;font-size:12px;margin-top:2px">{p}</div></div></div>' for s,c,n,k,p in [(12,LIME,'Charred Aubergine Bowl','480 kcal','42'),(13,APR,'Lime & Tahini Chicken','560 kcal','46'),(14,AUB,'Green Goddess Salad','340 kcal','38')])}<div style="position:absolute;left:14px;right:14px;bottom:14px;background:{LIME};border-radius:30px;text-align:center;padding:12px;font-weight:800;font-size:12px">View basket · 2 items</div></div></div>'''
def post(kind,i):
    if kind==0:return f'<div style="background:{LIME};width:100%;height:100%;position:relative;color:{AUB}"><div class="serif" style="position:absolute;left:10px;top:10px;font-size:20px;line-height:.95">Eat well.<br><em>Taste more.</em></div></div>'
    if kind==1:return f'<div style="width:100%;height:100%">{bowl(20+i,120,AUB,LIME,AUB)}</div>'
    if kind==2:return f'<div style="background:{AUB};width:100%;height:100%;display:flex;align-items:center;justify-content:center"><div style="width:56%">{lk(LIME,"mg")}</div></div>'
    if kind==3:return f'<div style="width:100%;height:100%">{bowl(30+i,120,APR)}</div>'
    if kind==4:return f'<div style="background:#fff;width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:13px;text-align:center;padding:10px;color:{AUB}">480 kcal.<br>0 compromise.</div>'
    return f'<div style="width:100%;height:100%">{bowl(40+i,120,LIME)}</div>'
grid=''.join(f'<div style="width:110px;height:110px;overflow:hidden">{post([0,1,2,3,4,5,2,0,1][i],i)}</div>' for i in range(9))
P.append(page('#E9E1D0',hdr('4.7','Digital: web, app & social','الموقع والتطبيق والسوشيال','APPLICATIONS')+f'<div class="abs" style="left:110px;top:180px">{site}</div><div class="abs" style="left:890px;top:180px">{phone}</div><div class="abs" style="left:1155px;top:180px;display:grid;grid-template-columns:repeat(3,1fr);gap:3px;width:336px">{grid}</div><div class="note" style="left:1155px;top:540px;width:336px;font-size:16px">Feed rhythm: bowl · colour block · bowl · quote. Never more than two lime tiles in a row.</div><div class="note" style="left:110px;bottom:50px;width:760px">Web: arch hero, lime CTA, ivory canvas. App: bowl thumbnails in arch masks, nutrition on every card.</div>'))
